package com.wwwwz.aigcs.compat;

import java.lang.reflect.Method;
import java.util.ServiceLoader;

import com.wwwwz.aigcs.AIGCsM4CnE;

import net.neoforged.fml.ModList;

/**
 * Best effort integration with the optional chunk loading mods.
 * <p>
 * The preload feature is built on the vanilla chunk system, so it automatically
 * benefits from a replaced engine: with <em>c2me</em> installed the chunk
 * requests made by {@link com.wwwwz.aigcs.server.preload.ServerPreloadManager}
 * are generated by c2me's parallel engine instead of the vanilla worker pool.
 * <p>
 * <em>Chunky</em> is detected so the GUI can warn when both tools are about to
 * preload the same area. Everything is resolved reflectively, so neither mod
 * becomes a hard dependency.
 */
public final class ModCompat {
    private static final String C2ME = "c2me";
    private static final String CHUNKY = "chunky";
    private static final String CHUNKY_API = "org.popcraft.chunky.api.ChunkyAPI";

    private static Boolean c2meLoaded;
    private static Boolean chunkyLoaded;
    private static Object chunkyApi;
    private static boolean chunkyApiResolved;
    private static long chunkyCheckedAt;
    private static boolean chunkyRunning;

    private ModCompat() {
    }

    public static boolean c2meLoaded() {
        if (c2meLoaded == null) {
            c2meLoaded = isLoaded(C2ME);
        }
        return c2meLoaded;
    }

    public static boolean chunkyLoaded() {
        if (chunkyLoaded == null) {
            chunkyLoaded = isLoaded(CHUNKY);
        }
        return chunkyLoaded;
    }

    private static boolean isLoaded(String modId) {
        try {
            return ModList.get() != null && ModList.get().isLoaded(modId);
        } catch (RuntimeException | LinkageError exception) {
            return false;
        }
    }

    /**
     * @return {@code true} when chunky is installed and currently runs a
     *         generation task, so the mod's own preload should stay out of the
     *         way
     */
    public static boolean chunkyRunning() {
        if (!chunkyLoaded()) {
            return false;
        }
        long now = System.currentTimeMillis();
        if (now - chunkyCheckedAt < 2000L) {
            return chunkyRunning;
        }
        chunkyCheckedAt = now;
        Object api = chunkyApi();
        if (api == null) {
            chunkyRunning = false;
            return false;
        }
        try {
            Method method = api.getClass().getMethod("isRunning", String.class);
            String world = currentWorldName();
            Object result = method.invoke(api, world);
            chunkyRunning = result instanceof Boolean running && running;
        } catch (ReflectiveOperationException | RuntimeException exception) {
            chunkyRunning = false;
        }
        return chunkyRunning;
    }

    /** Forgets the cached chunky state, for example after switching worlds. */
    public static void invalidate() {
        chunkyCheckedAt = 0L;
        chunkyRunning = false;
    }

    private static Object chunkyApi() {
        if (chunkyApiResolved) {
            return chunkyApi;
        }
        chunkyApiResolved = true;
        try {
            Class<?> type = Class.forName(CHUNKY_API);
            for (Object candidate : ServiceLoader.load(type)) {
                chunkyApi = candidate;
                break;
            }
        } catch (Throwable throwable) {
            AIGCsM4CnE.LOGGER.debug("Chunky API not available: {}", throwable.toString());
            chunkyApi = null;
        }
        return chunkyApi;
    }

    private static String currentWorldName() {
        try {
            net.minecraft.server.MinecraftServer server = net.neoforged.neoforge.server.ServerLifecycleHooks
                    .getCurrentServer();
            if (server != null) {
                return server.getWorldData().getLevelName();
            }
        } catch (RuntimeException | LinkageError ignored) {
            // Server lifecycle hooks are not available on a pure client.
        }
        return "";
    }
}
